code="from flask import Flask\nimport os, threading, time, requests, pytz\nfrom datetime import datetime\napp=Flask(__name__)\nTELEGRAM_BOT_TOKEN=os.environ.get('TELEGRAM_BOT_TOKEN')\nTELEGRAM_CHAT_ID=os.environ.get('TELEGRAM_CHAT_ID')\nALPACA_KEY=os.environ.get('ALPACA_API_KEY')\nALPACA_SECRET=os.environ.get('ALPACA_SECRET_KEY')\nALPACA_BASE='https://paper-api.alpaca.markets'\ndef send_tg(msg):\n    print(msg)\n    try:\n        if TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID:\n            requests.post(f'https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage', json={'chat_id': TELEGRAM_CHAT_ID, 'text': msg}, timeout=10)\n    except Exception as e:\n        print(f'TG Error: {e}')\ndef trading_loop():\n    send_tg('Ross Bot FREE Started - LIVE on Render!')\n    tz=pytz.timezone('US/Eastern')\n    while True:\n        try:\n            now=datetime.now(tz)\n            # 9:30 AM EST trading logic\n            if now.weekday() < 5 and now.hour == 9 and now.minute == 30:\n                send_tg(f'Checking market {now}')\n                # Add your Ross strategy here - example placeholder\n                # Your real strategy will run here\n                time.sleep(60)\n            time.sleep(20)\n        except Exception as e:\n            print(f'Loop error: {e}')\n            time.sleep(30)\napp.add_url_rule('/', 'home', lambda: 'Ross Bot FREE - FULL TRADING BOT LIVE!')\napp.add_url_rule('/health', 'health', lambda: 'OK')\nif __name__=='__main__':\n    threading.Thread(target=trading_loop, daemon=True).start()\n    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 10000)))\n"
exec(code)
